algorithms.pseudocode:
function GEODESIC_DISTANCE(u, v):
  require Nonneg(u) and Nonneg(v) and SameMargins(u, v)
  return |v[0,0,0] - u[0,0,0]|

function FIBER_AND_DIAMETER(u):
  lower <- max over cells c with M3(c)=+1 of (-u[c])
  upper <- min over cells c with M3(c)=-1 of ( u[c])
  members <- [ u + t*M3 : t = lower .. upper ]
  return (members, upper - lower)
